// ============================================================================
// Behavior-DSL immediate assertions -- Yosys-checkable subset
// Generated by t27c gen-behavior-sva-yosys
//
// Yosys read_verilog -sv -formal accepts neither `property ... endproperty`
// nor inline `assert property (@(posedge clk) ...)`. It accepts immediate
// assertions inside `always`, which is what this file emits, so these
// properties can actually be proved:
//
//   yosys -p 'read_verilog -sv -formal <this>; prep -top behavior_yosys; \
//             async2sync; chformal -lower; \
//             sat -verify -prove-asserts -seq 8 -tempinduct'
// phi^2 + 1/phi^2 = 3 | TRINITY
// ============================================================================

`default_nettype none

module behavior_yosys (
    input wire clk,
    input wire rst_n,
    input wire running,
    input wire full
);

// ----------------------------------------------------------------------------
// Behavior: engine_busy_safety
// Given:    running
// When:     posedge clk
// Then:     set full
// ----------------------------------------------------------------------------
always @(posedge clk) begin
    if (rst_n) begin
        a_0_engine_busy_safety: assert (!(running) || (full));
    end
end

// ----------------------------------------------------------------------------
// Behavior: irq_clear_on_reset
// Given:    reset inactive
// When:     posedge clk
// Then:     after 1 cycles set full
// ----------------------------------------------------------------------------
always @(posedge clk) begin
    if (rst_n && $past(rst_n)) begin
        a_1_irq_clear_on_reset: assert (!($past(rst_n, 1)) || (full));
    end
end

endmodule

`default_nettype wire
